SOUND_ON = True
_AUDIO = None


def _open_audio():
    """Open a persistent aplay process (no files: synthesized PCM).
    Minimal ALSA buffer/period so each tic sounds immediately.
    Warm-up: 0.2 s of silence so ALSA opens the device BEFORE the first
    real tic (otherwise the first tics pile up in the pipe and sound late)."""
    global _AUDIO
    try:
        import subprocess as _sp
        _AUDIO = _sp.Popen(
            ["aplay", "-q", "--period-size=128", "--buffer-size=256", "-f", "S16_LE", "-r", "44100", "-c", "1", "-"],
            stdin=_sp.PIPE, stdout=_sp.DEVNULL, stderr=_sp.DEVNULL,
        )
        # Warm-up: force the device open (0.2 s of silence) before first real tic
        try:
            _AUDIO.stdin.write(b"\x00" * 17640)
            _AUDIO.stdin.flush()
            time.sleep(0.1)
        except Exception:
            pass
    except Exception:
        _AUDIO = None


def _close_audio():
    """Close the persistent aplay (frees the PCM device for TTS)."""
    global _AUDIO
    if _AUDIO is not None:
        try:
            _AUDIO.stdin.close()
        except Exception:
            pass
        try:
            _AUDIO.terminate()
        except Exception:
            pass
        _AUDIO = None


def _reopen_audio():
    """Reopen the persistent aplay after TTS (device was busy)."""
    _open_audio()


def _tic():
    """Play a teletype-style 'tick': a very short high transient (4 kHz noise,
    1.5 ms) followed by a low body (250 Hz sine, 8 ms). Mimics the classic
    Wargames terminal clack. Synthesized in memory (no files)."""
    if _AUDIO is None or _AUDIO.poll() is not None:
        return
    import math
    import random
    import struct
    sr = 44100

    def _bandpass(x, center, Q):
        w0 = 2 * math.pi * center / sr
        alpha = math.sin(w0) / (2 * Q)
        b0, b1, b2 = alpha, 0.0, -alpha
        a0, a1, a2 = 1 + alpha, -2 * math.cos(w0), 1 - alpha
        b0, b1, b2 = b0 / a0, b1 / a0, b2 / a0
        a1, a2 = a1 / a0, a2 / a0
        y = [0.0] * len(x)
        x1 = x2 = y1 = y2 = 0.0
        for i, v in enumerate(x):
            y0 = b0 * v + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
            x2, x1 = x1, v
            y2, y1 = y1, y0
            y[i] = y0
        return y

    # Transient: 1.5 ms noise, very fast decay, bandpass 4 kHz
    n1 = int(sr * 0.0015)
    click = [(random.random() * 2 - 1) * math.exp(-i / 5.0) for i in range(n1)]
    click = _bandpass(click, 4000.0, 8.0)
    # Body: 250 Hz sine, 8 ms, fast decay
    n2 = int(sr * 0.008)
    body = [math.sin(2 * math.pi * 250 * i / sr) * math.exp(-i / (sr * 0.0018)) for i in range(n2)]
    # Assemble: click + tiny gap + body
    samples = list(click) + [0.0] * int(sr * 0.0005) + [b * 0.5 for b in body]
    gain = 0.19
    pcm = bytearray()
    for s in samples:
        pcm += struct.pack("<h", int(max(-1.0, min(1.0, s)) * gain * 32767))
    try:
        _AUDIO.stdin.write(bytes(pcm))
        _AUDIO.stdin.flush()
    except Exception:
        pass


def _skip_pressed():
    """True if the user pressed SPACE during the typewriter (consumes it). Non-blocking."""
    try:
        import select
        if select.select([0], [], [], 0)[0]:
            return os.read(0, 1) == b" "
    except Exception:
        pass
    return False


def _read_key():
    """Non-blocking read of ONE raw key during the typewriter (cbreak mode).
    Returns the byte (b" ", b"\t", b"\x12"...) or None if no key pressed.
    Used for barge-in: Tab = add text info, Ctrl+R = add voice info."""
    try:
        import select
        if select.select([0], [], [], 0)[0]:
            return os.read(0, 1)
    except Exception:
        pass
    return None


def _barge_input(prompt="  » "):
    """Raw line input for barge-in text (no tic, no history).
    Called AFTER the typewriter stops, with the terminal restored."""
    import termios, tty
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    sys.stdout.write(prompt)
    sys.stdout.flush()
    buf = []
    try:
        tty.setraw(fd)
        while True:
            ch = sys.stdin.read(1)
            if ch in ("\r", "\n"):
                sys.stdout.write("\r\n")
                sys.stdout.flush()
                break
            if ch in ("\x03", "\x04"):  # Ctrl+C / Ctrl+D cancels
                sys.stdout.write("\r\n")
                sys.stdout.flush()
                return ""
            if ch in ("\x7f", "\x08"):  # backspace
                if buf:
                    buf.pop()
                    sys.stdout.write("\b \b")
                    sys.stdout.flush()
            elif ch.isprintable():
                buf.append(ch)
                sys.stdout.write(ch)
                sys.stdout.flush()
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
    return "".join(buf)


def _cbreak_on():
    """Enable cbreak mode (each key is available instantly, no echo) if there is a tty.
    Returns (fd, old) to restore with _cbreak_off, or (None, None)."""
    try:
        import termios, tty
        fd = sys.stdin.fileno()
        old = termios.tcgetattr(fd)
        tty.setcbreak(fd)
        return fd, old
    except Exception:
        return None, None


def _cbreak_off(fd, old):
    if fd is not None:
        try:
            import termios
            termios.tcsetattr(fd, termios.TCSADRAIN, old)
        except Exception:
            pass


def _out(s=""):
    """Write to stdout converting LF to explicit CRLF (does not depend on ONLCR
    of the tty). The input (_input_tic) already writes explicit CRLF; LLM output
    must do the same or the cursor will not return to column 0 -> staircase effect."""
    sys.stdout.write(s.replace("\n", chr(13) + "\n"))
    sys.stdout.flush()


