_LOCAL_CONTEXT = 32768
_cloud_context = int(os.environ.get("AIOS_CLOUD_CONTEXT", "128000"))


def _ram_gb():
    """Total RAM in GB (rounded) from /proc/meminfo — same criterion as setup.py/status.py."""
    try:
        with open("/proc/meminfo", "r") as f:
            for line in f:
                if line.startswith("MemTotal:"):
                    kb = int(line.split()[1])
                    return max(1, kb // (1024 * 1024))
    except Exception:
        pass
    return 8


def _auto_context(ram_gb):
    """Auto-select context by RAM (mirror of setup.py auto_context)."""
    if ram_gb <= 8:
        return 8192
    elif ram_gb <= 16:
        return 32768
    else:
        return 65536


# Real local context according to the machine's RAM (was hardcoded to 32K — latent bug
# on ≤8GB laptops where the server only has 8K and compression used 32K)
_LOCAL_CONTEXT = _auto_context(_ram_gb())

# Relative max_tokens: cloud needs margin for reasoning_content (DeepSeek can spend
# hundreds of tokens thinking; 512 ran out → "empty response" with finish=length);
# local = 1/8 of RAM-derived context (leaves 7/8 for system+tools+history)
if os.environ.get("AIOS_MODE") in ("cloud", "hybrid"):
    MAX_TOKENS = max(4096, _cloud_context // 4)
else:
    MAX_TOKENS = max(512, _LOCAL_CONTEXT // 8)
    if THINK_LOCAL:
        # Reasoning (thinking) consumes tokens BEFORE the visible response;
        # with a small budget the model stops at finish=length and returns empty.
        MAX_TOKENS = max(2048, _LOCAL_CONTEXT // 8)

MAX_HISTORY_TOKENS = int(_LOCAL_CONTEXT * 0.95) if os.environ.get("AIOS_MODE") in ("local", "hybrid") else int(_cloud_context * 0.06)
SESSION_FILE = Path("data") / f"session_{os.environ.get('AIOS_MODE', 'local')}.json"


def _estimate_tokens(text: str) -> int:
    """Estimate tokens via llama.cpp tokenize endpoint (accurate)."""
    try:
        resp = requests.post(
            LLAMA_SERVER + "/tokenize",
            json={"content": text},
            timeout=5
        )
        if resp.status_code == 200:
            return len(resp.json().get("tokens", []))
    except Exception:
        pass
    # Fallback: rough estimate. len//2 OVERESTIMATES for natural text in all
    # European languages (measured 2.8-4.4 chars/token) and matches technical
    # content (~2 chars/token). Overestimating is safe: compression triggers
    # early, never late (Cloudflare 100s limit).
    return len(text) // 2


def _rules_common():
    # Only say "do not think" when thinking is off. When it is on, let Qwen3 reason
    # (more accurate); the thinking block is cleaned in _clean().
    _no_think = ""  # thinking is controlled via chat_template_kwargs (enable_thinking), not <think> tags
    return (
        "Always respond in the same language the user writes in.\n"
        "Be concise.\n"
        "For questions about the CURRENT state of the system (RAM, disk, processes, services, installed packages, network), ALWAYS check with a tool first — never answer from memory.\n"
        "For 'what programs/apps are installed' or 'is X installed', use the list_desktop_apps tool (never answer from memory).\n"
        "If you run a command, show its output to the user.\n"
        "Before destructive commands (rm -rf, dd, mkfs, fdisk), warn and ask for confirmation.\n"
        "If a command fails with Permission denied or Operation not permitted, retry it with sudo. When you run a command with sudo, the system will automatically ask the user for the sudo password (masked) if it is needed — do NOT ask the user to run /sudo or to type a password; just emit the sudo command and it will be handled.\n"
        "If a systemd service fails to start with 'A dependency job for ... failed', do NOT run the same `systemctl start` again. Inspect the failing dependency first with `systemctl status <dependency>` and `journalctl -u <dependency> --no-pager`. If the failure is due to the live session (e.g. Docker socket cannot bind in overlay), tell the user and stop.\n"
        "If you don't know something, say so honestly: 'I don't know'.\n"
        + _no_think
        + "\nFor complex tasks, do NOT explain - EXECUTE. Generate a plan with numbered steps and execute each step automatically, verifying the result before continuing.\n"
        "NEVER end your turn with a promise to act ('I'll do it now', 'vamos a hacerlo', 'let me...'). If you intend to run a tool, emit the tool call in the SAME turn immediately — do not wait for the user to say 'ok'.\n"
        "Example:\n"
        "  User: \"install WordPress with Docker and MariaDB\"\n"
        "  Agent: run step 1 (check Docker), step 2 (create compose), step 3 (start), step 4 (verify). Without asking, without explaining. Just execute.\n"
        "\nIf a script expects interactive input (input(), confirmations, passwords), use process_start. Do NOT use run_command for interactive scripts."
    )


def _is_trivial_query(q: str) -> bool:
    """True for greetings/acknowledgements/short queries — not reusable
    procedure knowledge worth caching in procedural memory."""
    _TRIVIAL = {"hola", "buenas", "hello", "hi", "hey", "gracias", "thanks",
                "ok", "vale", "si", "s\u00ed", "adelante", "perfecto", "genial"}
    qn = re.sub(r"[^a-z\u00e1\u00e9\u00ed\u00f3\u00fa\u00f1\u00fc0-9 ]", "", q.lower()).strip()
    if len(qn) < 12:
        return True
    words = set(qn.split())
    if words & _TRIVIAL:
        return True
    return False


